SELECT * FROM racer_results rr INNER JOIN entry_racers er ON rr.entry_racer_id=er.id INNER JOIN entry_categories ec ON er.entry_category_id=ec.id INNER JOIN point_series_racers psr ON rr.id=psr.racer_result_id INNER JOIN point_series ps ON psr.point_series_id=ps.id WHERE ec.deleted=0 AND er.deleted=0 AND rr.deleted=0 AND ps.deleted=0 AND ec.id=24693 AND ps.is_active=1 AND ps.publishes_on_ressys=1;
